code='''def transform(grid):
    # Full-width and full-height uniform lines divide the grid into tiles.
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def spans(n, separators):
        out = []
        start = 0
        for i in range(n):
            if i in separators:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # The most common non-divider color is the tile background.
    vals = [grid[r][c] for a, b in rs for r in range(a, b)
            for x, y in cs for c in range(x, y)]
    background = max(set(vals), key=vals.count)
    result = []
    for a, b in rs:
        row_out = []
        for x, y in cs:
            markers = sum(grid[r][c] != background
                          for r in range(a, b) for c in range(x, y))
            row_out.append(1 if markers >= 2 else background)
        result.append(row_out)
    return result
'''
